from django.db import migrations, models


def move_sampling_into_technical(apps, schema_editor):
    from thiet_ke_sp.models import ProductDevelopment, Status
    from thiet_ke_sp.services import workflow as wf

    ProductDevelopment.objects.filter(status=Status.PAUSED, paused_from_status=Status.SAMPLING).update(
        paused_from_status=Status.TECHNICAL,
    )
    ProductDevelopment.objects.filter(status=Status.PAUSED, paused_from_status=Status.SAMPLE_REVISE).update(
        paused_from_status=Status.TECHNICAL_REVISE,
    )
    moves = (
        (Status.SAMPLING, Status.TECHNICAL, False),
        (Status.SAMPLE_REVISE, Status.TECHNICAL_REVISE, True),
    )
    for old, new, revision in moves:
        rows = ProductDevelopment.objects.filter(status=old).select_related('technician', 'owner', 'proposer')
        for dossier in rows:
            actor = dossier.technician or dossier.owner or dossier.proposer
            wf._transition(
                dossier, new, actor, 'step_inserted',
                'Thêm bước Kỹ thuật trước làm mẫu.',
                revision=revision,
            )


def noop(apps, schema_editor):
    return None


